INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3346004, 462755, 12733, '<td valign="top">I like the colors and the great DOF. It''s an interesting church building. I recall one thread that had comments like I take off points for a long title that incorporates the name of the challenge. That''s because the picture should pretty much say it all. I don''t take off points unless the title is the only thing relevant to the challenge, but I do prefer to see a picture that needs only a title that says what it is (i.e. country church).</td>', 'I like the colors and the great DOF. It''s an interesting church building. I recall one thread that had comments like I take off points for a long title that incorporates the name of the challenge. That''s because the picture should pretty much say it all. I don''t take off points unless the title is the only thing relevant to the challenge, but I do prefer to see a picture that needs only a title that says what it is (i.e. country church).', '2007-02-08 21:22:32.000000', NULL, 1),
(3346005, 462160, 12733, '<td valign="top">cute</td>', 'cute', '2007-02-08 21:23:23.000000', NULL, 1),
