INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3363982, 464339, 72058, '<td valign="top">Dissapointed with the comments made here.  People seem to be voting based upon their animal rights belief and not on the quality of the image.  I thought this was a photography contest?  As a matter of fact these animals looked very happy to me, were being well looked after and are not "caged" in any way, shape or form as one comment stated!  The one leaning against the wall was basking in the warm afternoon sun.  They are also doing a GOOD service as they are part of a captive breeding programme that helps save endangered species.  Look up the world renowned Durrell Wildlife Preservation Trust - something I support.  I suppose that part of the problem was my fault in not conveying the above in an image but it would have been very difficult to do without an extraordinarily long title!  Maybe I should have chosen a different subject matter or perhaps voters should give the benefit of the doubt in that the subject does meet the challenge rather than use this site to express their political views???</td>', 'Dissapointed with the comments made here.  People seem to be voting based upon their animal rights belief and not on the quality of the image.  I thought this was a photography contest?  As a matter of fact these animals looked very happy to me, were being well looked after and are not "caged" in any way, shape or form as one comment stated!  The one leaning against the wall was basking in the warm afternoon sun.  They are also doing a GOOD service as they are part of a captive breeding programme that helps save endangered species.  Look up the world renowned Durrell Wildlife Preservation Trust - something I support.  I suppose that part of the problem was my fault in not conveying the above in an image but it would have been very difficult to do without an extraordinarily long title!  Maybe I should have chosen a different subject matter or perhaps voters should give the benefit of the doubt in that the subject does meet the challenge rather than use this site to express their political views???', '2007-02-14 04:58:14.000000', NULL, 0),
(3364011, 462996, 56167, '<td valign="top">congratulations on the ribbion, I said it deserved one and I was right, wish I could get my own photos so perfect. :-)</td>', 'congratulations on the ribbion, I said it deserved one and I was right, wish I could get my own photos so perfect. :-)', '2007-02-14 05:14:55.000000', NULL, 0),
